
#[cfg(test)]mod fire70_development_tests {
    use super::*;
    const RAW:&[u8]=include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-mass69-fire70-inspection\20261024-155206-240172\1819.definition.txt");
    fn catalog(raw:&[u8])->SpriteActionCatalog{SpriteActionCatalog::parse_for_inspection(&[b"11297 0 0\n".as_slice(),raw].concat(),super::super::sprite_actions::ActionLimits::default()).unwrap()}
    fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.insert(70);w}
    fn packet(w:&World,targets:&[(u32,bool)])->Vec<u8>{let a=w.own_actor().unwrap();let mut b=vec![57,18];b.extend(a.id.to_le_bytes());b.extend(a.x.to_le_bytes());b.extend(a.y.to_le_bytes());b.push(3);b.extend(7_u32.to_le_bytes());b.extend(1819_u16.to_le_bytes());b.extend([0,0,0]);b.extend((targets.len()as u16).to_le_bytes());for&(id,hit)in targets{b.extend(id.to_le_bytes());b.push(if hit{32}else{0});}b}
    fn event(w:&World)->EnteredEvent{let a=w.own_actor().unwrap();EnteredEvent{actor:a.id,sequence:a.action_sequence,action:18,frame:1,event:"Hit".into(),sound:None,prepared_audio:None}}
    fn model()->Effects{let mut e=Effects::default();let mut a=qualify_fire70(&catalog(RAW)).unwrap().remove(0).2;for f in &mut a.frames{f.events.retain(|e|!matches!(e,FrameEvent::Sound(_)));}e.clips.insert(1819,Clip::new(Arc::new(a)).unwrap());e}
    #[test]fn original_firestorm_is_class_zero_screen_without_extra_shadow_or_audio_substitution(){
        assert_eq!(qualify_fire70(&catalog(RAW)).unwrap()[0].2.frames.len(),14);let text=String::from_utf8(RAW.to_vec()).unwrap();for(a,b)in[("[710","<710"),("109.effect(0 -1)","109.effect(1 -1)"),("104.attr(8)","104.attr(128)"),("0.6:4!","0.6:5!"),("0.13:6","0.13:5")]{assert!(text.contains(a));assert!(qualify_fire70(&catalog(text.replace(a,b).as_bytes())).is_err());}
    }
    #[test]fn exact_native_callbacks_put_audio_at_zero_Hit_at873_and_retire2369ms(){
        let mut p=Clip::new(Arc::new(qualify_fire70(&catalog(RAW)).unwrap().remove(0).2)).unwrap().start();let mut s=p.advance(0).unwrap();let(mut sound,mut hit,mut at)=(vec![],vec![],0);loop{for c in &s.crossed_cues{match c.event{FrameEvent::Sound(710)=>sound.push(at),FrameEvent::Hit=>hit.push(at),_=>{}}}if s.finished{break;}at=p.next_callback_millis().unwrap();s=p.advance(at*1_000_000).unwrap();}assert_eq!(sound,vec![0]);assert_eq!(hit,vec![873]);assert_eq!(at,2369);assert_eq!(s.source_frame,0);
        let mut p=Clip::new(Arc::new(qualify_fire70(&catalog(RAW)).unwrap().remove(0).2)).unwrap().start();p.advance(0).unwrap();assert_eq!(p.advance(1_000_000_000).unwrap().source_frame,2);assert_eq!(p.next_callback_millis(),Some(1125));
    }
    #[test]fn malformed_packet_tail_marker_or_class_is_not_a_partial_world_update(){
        let mut w=world();let id=w.own_actor().unwrap().id;let b=packet(&w,&[(id,false)]);assert_eq!(decode(&b).unwrap().unwrap().graphics,1819);let mut wrong=b.clone();wrong[17]=8;assert!(decode(&wrong).unwrap().is_none());for bad in [b[..b.len()-1].to_vec(),{let mut b=b.clone();*b.last_mut().unwrap()=1;b}]{let before=serde_json::to_value(&w).unwrap();assert!(w.accept(&bad).is_err());assert_eq!(serde_json::to_value(&w).unwrap(),before);}
    }
    #[test]fn zero_or_missed_targets_do_not_move_the_wire_origin_or_bind_first_actor(){
        for targets in [vec![],vec![(0x71234567,false)]]{let mut w=world();let own=w.own_actor().unwrap().clone();w.accept(&packet(&w,&targets)).unwrap();let cue=w.many_attacks.last().unwrap();assert_eq!(cue.target_origin,None);assert_eq!(cue.attack.position,[own.x,own.y]);w.actors.get_mut(&own.id).unwrap().x+=7;let mut e=model();e.update(&w,[&event(&w)].into_iter(),0);assert_eq!(e.active[0].cue.attack.position,[own.x,own.y]);}
    }
    #[test]fn Hit_is_diagnostic_and_same_source_history_cannot_restart_or_repeat_it(){
        let mut w=world();let id=w.own_actor().unwrap().id;w.accept(&packet(&w,&[(id,true)])).unwrap();let before=serde_json::to_value(&w).unwrap();let launch=event(&w);let mut e=model();assert!(e.update(&w,[&launch].into_iter(),0).is_empty());let mut at=0;let mut diagnostics=vec![];while !e.active[0].finished{at=e.active[0].playback.next_callback_millis().unwrap();assert!(e.update(&w,std::iter::empty(),at*1_000_000).is_empty());diagnostics.extend(e.non_audio.clone());}assert_eq!(e.hits,1);assert_eq!(diagnostics.len(),1);assert_eq!(diagnostics[0]["event"],"FirestormHit");assert_eq!(diagnostics[0]["authority_callback"],false);let mut restored=model();restored.restore_history(e.history());restored.update(&w,[&launch].into_iter(),(at+1)*1_000_000);assert!(restored.active.iter().all(|a|a.finished));assert_eq!(restored.started,1);assert_eq!(serde_json::to_value(&w).unwrap(),before);
    }
    #[test]fn failed_reprepare_retires_once_and_does_not_create_a_fallback_clip(){
        let mut w=world();w.accept(&packet(&w,&[])).unwrap();let launch=event(&w);let mut e=model();e.update(&w,[&launch].into_iter(),0);let mut restored=Effects::default();restored.restore_history(e.history());restored.error=Some("cancelled assets".into());restored.update(&w,std::iter::empty(),125_000_000);assert!(restored.history().active_sequences().is_empty());assert_eq!(restored.omitted,1);restored.update(&w,[&launch].into_iter(),250_000_000);assert_eq!(restored.omitted,1);
    }
    #[test]
    #[ignore="LITO_SHARED_RESOURCE_ROOT; original1819/710, frozen wire origin and same-source history; memory fragments only"]
    fn original_firestorm_bank_has_one_screen_layer_and_world_audio_once(){
        let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=world();w.accept(&packet(&w,&[])).unwrap();let own=w.own_actor().unwrap().clone();let launch=event(&w);let mut e=Effects::default();e.prepare(&root,&w,&cancel);assert!(e.error.is_none());e.update(&w,[&launch].into_iter(),0);let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};let mut q=vec![];let(_,audio)=e.draw_to(&mut Target::Fragments(&mut q),view,0);assert_eq!(q.len(),1);assert!(matches!(q[0].mix,Mix::Screen));assert_eq!(q[0].position,WorldCell{x:i32::from(own.x),y:i32::from(own.y)});assert_eq!(audio.iter().filter(|e|e.actor==0&&e.sound==Some(710)&&e.prepared_audio.is_some()).count(),1);drop(q);let h=e.history();w.actors.clear();w.many_attacks.clear();w.learned_skills.clear();let mut restored=Effects::default();restored.restore_history(h);restored.prepare(&root,&w,&cancel);restored.update(&w,std::iter::empty(),125_000_000);let mut q=vec![];let(_,audio)=restored.draw_to(&mut Target::Fragments(&mut q),view,125_000_000);assert_eq!(q.len(),1);assert!(audio.is_empty());
    }
}
